def change_base(x: int, base: int) -> str:
    if x < 0:
        raise ValueError("x must be non-negative")
    if base < 2 or base > 9:
        raise ValueError("base must be between 2 and 9")

    if x == 0:
        return '0'

    result = ''
    while x > 0:
        result = str(x % base) + result
        x //= base

    return result

